def length_of_sequence(arr, n):
    if arr.count(n) != 2:
        return 0
    a = arr.index(n)
    b = arr.index(n, a + 1)
    return b - a + 1

import re, random

def roll(desc, verbose=False):
    if not isinstance(desc,str): return False

    ans = re.findall(r'^(\d*)d(\d+)(([+\-]\d+)*)$', desc.replace(' ',''))

    if len(ans) == 0: return False

    dct = {i: eval(v) for i,v in enumerate(ans[0]) if v}
    dices = {'dice':     [ 1+random.randrange(dct[1]) for i in range(dct.get(0, 1)) ],
             'modifier': dct.get(2, 0) }

    return dices if verbose else sum(dices['dice']) + dices['modifier']

def to_1D(x, y, size):
    return y * size[0] + x    

def to_2D(n, size):
    return (n % size[0], n // size[0])

def solomons_quest(arr):
    pos, lvl = [0,0], 0
    for dilat,dir,dist in arr:
        lvl += dilat
        pos[dir in [0,2]] += dist * 2**lvl * (-1)**( dir in [2,3] )
    return pos

def hot_singles(arr1, arr2):
    a = []
    for x in arr1 + arr2:
        if x in set(arr1) ^ set(arr2) and x not in a: a.append(x)
    return a

