from heapq import heappush, heappopdef min_moves_to_opposite_parity():
    n = int(input())
    a = list(map(int, input().split()))
    edge = [[] for _ in range(n)]
    rev = [[] for _ in range(n)]
    inf = 10**9
    cost = [inf]*n
    hq = []
    for i, x in enumerate(a):
        if i+x < n:
            edge[i].append(i+x)
            rev[i+x].append(i)
            if (a[i] ^ a[i+x]) & 1:
                cost[i] = 1
        if i-x >= 0:
            edge[i].append(i-x)
            rev[i-x].append(i)
            if (a[i] ^ a[i-x]) & 1:
                cost[i] = 1
        if cost[i] == 1:
            hq.append((1, i))
    while hq:
        c, v = heappop(hq)
        if cost[v] < c:
            continue
        c += 1
        for dest in rev[v]:
            if cost[dest] > c:
                cost[dest] = c
                heappush(hq, (c, dest))
    for i in range(n):
        if cost[i] == inf:
            cost[i] = -1
    print(*cost)

def memoized(f):
    cache = {}
    def wrapped(k):
        v = cache.get(k)
        if v is None:
            v = cache[k] = f(k)
        return v
    return wrapped

@memoized
def fibonacci(n):
    if n in [0, 1]:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

def complete_binary_tree(a):
    def in_order(n=0):
        if n < len(a):
            yield from in_order(2 * n + 1)
            yield n
            yield from in_order(2 * n + 2)

    result = [None] * len(a)
    for i, x in zip(in_order(), a):
        result[i] = x
    return result

