class Solution:
    def rob(self, nums: List[int]) -> int:
        if not nums:
            return 0
        if len(nums) < 3:
            return max(nums)
        dp = [0] * len(nums)
        dp[0] = nums[0]
        dp[1] = max(nums[0], nums[1])

        for i in range(2, len(nums)):
            dp[i] = max(dp[i-2] + nums[i], dp[i-1])
        return max(dp)

def find_min_num(d, n=1):
    while div_num(n) != d:
        n += 1
    return n

def div_num(n):
    s = n**0.5
    return sum(2 for k in range(1, int(s)+1) if n % k == 0) - (s % 1 == 0)

MEMO = []

def sum_dif_rev(n):
    i = MEMO[-1] if MEMO else 0

    while len(MEMO) < n:
        i += 1
        r = int(str(i)[::-1])
        if i % 10 and r != i and (i + r) % abs(r - i) == 0:
            MEMO.append(i)

    return MEMO[n-1]

import heapqdef minimum_internet_connection_cost():
    n, k = list(map(int, input().split()))
    s = input()
    mostRecent = n
    best = []
    for room in range(n-1, -1, -1):
        if s[room] == '1':
            mostRecent = room
        best.append(mostRecent)
    best = best[::-1]
    dp = [0]
    vals = [(0,0)]
    for room in range(1, n + 1):
        new = dp[-1] + room
        if room - k - 1 >= 0:
            bestRout = best[room - k - 1]
            if bestRout <= (room - 1):
                covered = bestRout - k
                if covered >= 0:
                    try:
                        while len(vals) > 0 and vals[0][1] < covered:
                            heapq.heappop(vals)
                        if len(vals) > 0:
                            add = vals[0][0]
                            new2 = (bestRout + 1) + add
                            new = min(new2, new)
                    except Exception:
                        pass
                else:
                    new2 = (bestRout + 1)
                    new = min(new2, new)
        dp.append(new)
        heapq.heappush(vals, (new, room))
    print(new)

