def poohbear(s):

    def updateMem(func, v): mem[p] = func(mem.get(p, 0), v) % 256

    braces, stack = {}, []
    for i,c in enumerate(s):
        if c == 'W': stack.append(i)
        if c == 'E':
            braces[i] = stack[-1]
            braces[stack.pop()] = i

    mem, copy, output = {}, 0, []
    p, i = 0, 0
    while i < len(s):
        cmd = s[i]
        if   cmd == '>':  p += 1
        elif cmd == '<':  p -= 1
        elif cmd == 'p':  mem[p] = copy
        elif cmd == 'c':  copy = mem.get(p, 0)
        elif cmd == 'W':  i = i if bool(mem.get(p, 0)) else braces[i]
        elif cmd == 'E':  i = braces[i] if mem.get(p, 0) else i
        elif cmd == 'P':  output.append(chr(mem.get(p, 0)))
        elif cmd == 'N':  output.append(str(mem.get(p, 0)))
        elif cmd == '+':  updateMem(add,  1)
        elif cmd == '-':  updateMem(add, -1)
        elif cmd == 'L':  updateMem(add,  2)
        elif cmd == 'I':  updateMem(add, -2)
        elif cmd == 'T':  updateMem(mul,  2)
        elif cmd == 'V':  updateMem(fdiv, 2)
        elif cmd == 'Q':  updateMem(pow,  2)
        elif cmd == 'U':  updateMem(lambda a,b: int(pow(a, b)), .5)
        elif cmd == 'A':  updateMem(add,  copy)
        elif cmd == 'B':  updateMem(add, -copy)
        elif cmd == 'Y':  updateMem(mul,  copy)
        elif cmd == 'D':  updateMem(fdiv, copy)
        i += 1

    return ''.join(output)

# This is the Miller-Rabin test for primes, which works for super large n

import random

def even_odd(n):
    s, d = 0, n
    while d % 2 == 0:
          s += 1
          d >>= 1
    return s, d

def Miller_Rabin(a, p):
    s, d = even_odd(p-1)
    a = pow(a, d, p)
    if a == 1: return True
    for i in range(s):
        if a == p-1: return True
        a = pow(a, 2, p)
    return False

def is_prime(p):
    if p == 2: return True
    if p <= 1 or p % 2 == 0: return False
    return all(Miller_Rabin(random.randint(2,p-1),p) for _ in range(40))

import math

def divisors(n):
    divs = [1]
    for i in range(2,int(math.sqrt(n))+1):
        if n%i == 0:
            divs.extend([i,n//i])
    divs.extend([n])
    return list(set(divs))

