def mobius(n):
    sP, p = set(), 2
    while n>1 and p <= n**.5:
        while not n%p:
            if p in sP: return 0
            sP.add(p)
            n //= p
        p += 1 + (p!=2)
    return (-1)**((len(sP) + (n!= 1)) % 2)

def primeFactors(n):
    ret = ''
    for i in range(2, n + 1):
        num = 0
        while(n % i == 0):
            num += 1
            n /= i
        if num > 0:
            ret += '({}{})'.format(i, '**%d' % num if num > 1 else '')
        if n == 1:
            return ret

def totient(n):
    if not isinstance(n,int) or n<1: return 0

    phi = n >= 1 and n
    for p in range(2, int(n ** .5) + 1):
        if not n % p:
            phi -= phi // p
            while not n % p:
                n //= p
    if n > 1: phi -= phi // n
    return phi

