def tram(stops, descending, onboarding):
    return max(accumulate(o - d for d, o in zip(descending[:stops], onboarding)))

def zombie_shootout(zombies, distance, ammo, shot=0):

    if not zombies:
        return f'You shot all {shot} zombies.'

    if distance <= 0:
        return f'You shot {shot} zombies before being eaten: overwhelmed.'

    if not ammo:
        return f'You shot {shot} zombies before being eaten: ran out of ammo.'

    return zombie_shootout(zombies - 1, distance - 0.5, ammo - 1, shot + 1)

def count_cows(n):
    if not isinstance(n, int):
        return None
    return 1 if n < 3 else count_cows(n-1) + count_cows(n-3)

def bowling_score(rolls):
  "Compute the total score for a player's game of bowling."

  def is_spare(rolls):
    return 10 == sum(rolls[:2])

  def is_strike(rolls):
    return 10 == rolls[0]

  def calc_score(rolls, frame):
    return (sum(rolls) if frame == 10 else
            sum(rolls[:3]) + calc_score(rolls[1:], frame+1) if is_strike(rolls) else
            sum(rolls[:3]) + calc_score(rolls[2:], frame+1) if is_spare(rolls) else
            sum(rolls[:2]) + calc_score(rolls[2:], frame+1))

  return calc_score(rolls,1)

