        for i in range(n):
            for j in range(MAX_A):
                ruiseki[i + 1][j] = ruiseki[i][j]
                if a[i] - 1 == j:
                    ruiseki[i + 1][j] += 1
        ans = 0
        for num in set(a):
            l = 0
            r = n - 1
            cnt = 0
            while True:
                while True:
                    if a[l] != num:
                        l += 1
                    else:
                        break
                while True:
                    if a[r] != num:
                        r -= 1
                    else:
                        break
                if l == r:
                    ans = max(ans, cnt + 1)
