class Solution:
    def maxCandies(self, status: List[int], candies: List[int], keys: List[List[int]], containedBoxes: List[List[int]], initialBoxes: List[int]) -> int:
        # nested boxes
        reachable=[False]*len(status)
        visited=[False]*len(status)
        for box in initialBoxes:
            reachable[box]=True
        for i in range(len(containedBoxes)):
            for inside in containedBoxes[i]:
                reachable[inside]=False
        # we only start with initial boxes
        queue=initialBoxes
        target=[]
        ret=0
        while queue:
            for box in queue:
                if status[box]==1 and reachable[box] and not visited[box]:
                    ret+=candies[box]
                    visited[box]=True
                    for key in keys[box]:
                        if status[key]==0:
                            status[key]=1
                            if reachable[key]:
                                target.append(key)
                    for inside in containedBoxes[box]:
                        reachable[inside]=True
                        if status[inside]==1:
                            target.append(inside)
                else:
                    target.append(box)
            if target==queue:
                break
            queue=target
            target=[]
        return ret

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        # save all even subarray's length which between odds
        edge = []
        res = 0
        count = 0
        for i in nums:
            # odd
            if i % 2:
                # +1 because range from 0 to count when doing combination
                edge.append(count+1)
                count = 0
            # even
            else:
                count += 1
        edge.append(count+1)
        # no enough odd
        if len(edge)-1 < k:
            return 0
        else:
            # combination
            for i in range(len(edge)-k):
                res += edge[i] * edge[i+k]
            return res

