     for i in range(y1):
      for j in range(i+1, y1):
       area += abs(x1[i] - x1[j])*(y2 + (2*y3))
     for i in range(y3):
      for j in range(i+1, y3):
       area += abs(x3[i] - x3[j])*(y2 + (2*y1))
     for i in range(y2):
      for j in range(i+1, y2):
       area += abs(x2[i] - x2[j])*(y1 + y3)
