        ways = [0]*n
        frontier = []
        dist[s] = 0
        ways[s] = 1
        heappush(frontier,(0,s))
        while (len(frontier)>0):
            x = heappop(frontier)
            if x[0]!=dist[x[1]]:
                continue
            x = x[1]
            for (i,l) in adj[x]:
                if dist[x]+l<dist[i]:
                    dist[i] = dist[x]+l
                    ways[i] = ways[x]
                    heappush(frontier,(dist[i],i))
                elif dist[x]+l==dist[i]:
                    ways[i] = addM(ways[i],ways[x])
        return (dist,ways)
    n,m,s,t = map(int,sys.stdin.readline().split())
    s-=1
    t-=1
    adj = [[] for i in range(n)]
    jda = [[] for i in range(n)]
    edges = []
    for i in range(m):
        a,b,l = map(int,sys.stdin.readline().split())
        a-=1
        b-=1
        adj[a].append((b,l))
        jda[b].append((a,l))
        edges.append((a,b,l))
    one = dijk(adj,n,s)
    two = dijk(jda,n,t)
    for i in edges:
        if one[0][i[0]]+i[2]+two[0][i[1]]==one[0][t] and mulM(one[1][i[0]],two[1][i[1]])==one[1][t]:
            sys.stdout.write("YES\n")
        else:
            x = one[0][t]-1-one[0][i[0]]-two[0][i[1]]
            if x<=0:
                sys.stdout.write("NO\n")
            else:
                sys.stdout.write("CAN "+str(i[2]-x)+"\n")

def minimum_flour_delivery_cost(n, m, k, roads, storages):
    import heapq
    import sys

    if k == 0:
        return -1  # No storage means the bakery can't be opened.

    # Initialize distances as infinity
    distances = [sys.maxsize] * (n + 1)

    # Mark the storages
    storage_set = set(storages)

    # Create adjacency list for all cities
    adj_list = [[] for _ in range(n + 1)]
    for u, v, l in roads:
        adj_list[u].append((v, l))
        adj_list[v].append((u, l))

    # Use a priority queue for Dijkstra's algorithm
    pq = []

    # Initialize the priority queue with all storage cities and set their distances to 0
    for storage in storages:
        heapq.heappush(pq, (0, storage))
        distances[storage] = 0

    # Perform Dijkstra's algorithm from all storages
    while pq:
        current_dist, u = heapq.heappop(pq)

        if current_dist > distances[u]:
            continue

        for neighbor, weight in adj_list[u]:
            if distances[u] + weight < distances[neighbor]:
                distances[neighbor] = distances[u] + weight
                heapq.heappush(pq, (distances[neighbor], neighbor))

    # Find the minimum distance to any non-storage city
    min_cost = sys.maxsize
    for i in range(1, n + 1):
        if i not in storage_set:
            min_cost = min():
    n,m,k = (int(i) for i in input().split())
