import functoolsdef count_subsequences_ending_at_one():
    # cook your dish here
    def gcd(a, b):  
     if (a == 0): 
      return b 
     return gcd(b % a, a) 

    MAX=10001
    def func(ind, g, dp, n, a): 
     if (ind == n):  
      if (g == 1):  
       return 1
      else: 
       return 0
     if (dp[ind][g] != -1):  
      return dp[ind][g] 
     ans = (func(ind + 1, g, dp, n, a) + 
       func(ind + 1, gcd(a[ind], g),  
            dp, n, a)) 
     dp[ind][g] = ans 
     return dp[ind][g] 

    def countSubsequences(a, n):  
     dp = [[-1 for i in range(MAX)] 
        for i in range(n)] 
     count = 0
     for i in range(n):  
      count += func(i + 1, a[i], dp, n, a) 
     return count 
    test=int(stdin.readline())
    for _ in range(test):
     n=int(stdin.readline())
     list1=list(map(int,stdin.readline().split()))
     print(countSubsequences(list1,n))

def minimize_array_length():
    n = int(input())
    a = list(map(int, input().split()))

    dp = [[False] * (n + 1) for i in range(n + 1)]

    def solve(l, r):
        if dp[l][r]:
            return dp[l][r]
        if r - l == 1:
            dp[l][r] = (a[l], 1)
            return dp[l][r]
        tmp = 10 ** 9
        for i in range(l + 1, r):
            if solve(l, i)[0] == -1 or solve(i, r)[0] == -1:
                tmp = min(tmp, dp[l][i][1] + dp[i][r][1])
            elif solve(l, i) == solve(i, r):
                tmp = solve(l, i)[0] + 1
                dp[l][r] = (tmp, 1)
                return dp[l][r]
            else:
                tmp = min(tmp, 2)
        dp[l][r] = (-1, tmp)
        return dp[l][r]

    solve(0, n)
    print(dp[0][n][1])

