from collections import defaultdict as dddef find_max_palindromic_subpair_length():
    def find(a, b):
     n = len(a)
     m = len(b)
     dp = [[0]*(m+1) for i in range(n+1)]
     for i in range(n-1,-1, -1):
      for j in range(m-1, -1, -1):
       if a[i] == b[j]:
        dp[i][j] = dp[i+1][j+1] + 1
     mx = dd(int)
     ans = 0
     for i in range(n-1, -1, -1):
      for j in range(m-1, -1, -1):
       a = mx[(i+1, j)]
       b = mx[(i, j+1)]
       mx[(i, j)] = max([dp[i][j], a, b])
     for i in range(n):
      for j in range(m):
       c = dp[i][j]
       nxt = mx[(i+c, j+c)]
       cur = c + nxt
       ans = max(ans, cur)

     return 2*ans
    for case in range(int(input())):
     a, b = input().split()
     b = b[-1::-1]
     ans = find(a, b)
     print(ans)

def min_break_cost_to_eat_k_squares():
    mem = [[[0 for i in range(51)] for j in range(31)] for k in range(31)]


    def f(n, m, k):
        if mem[n][m][k]:
            return mem[n][m][k]
        if (n*m == k) or (k == 0):
            return 0
        cost = 10**9
        for x in range(1, n//2 + 1):
            for z in range(k+1):
                cost = min(cost, m*m + f(n-x, m, k-z) + f(x, m, z))
        for y in range(1, m//2 + 1):
            for z in range(k+1):
                cost = min(cost, n*n + f(n, m-y, k-z) + f(n, y, z))
        mem[n][m][k] = cost
        return cost


    t = int(input())
    for i in range(t):
        n, m, k = list(map(int, input().split()))
        print(f(n, m, k))

from sys import stdindef min_pixel_toggles_for_compressibility():
    #!/usr/bin/env python
    # coding:utf-8
    # Copyright (C) dirlt
    def run(n, m, pixels):
        ans = 1 << 30
        acc = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n):
            for j in range(m):
                acc[i + 1][j + 1] = acc[i + 1][j] + int(pixels[i][j])
            for j in range(m):
                acc[i + 1][j + 1] += acc[i][j + 1]
        # print(acc)
        for k in range(2, max(n, m) + 1):
            r, c = (n + k - 1) // k, (m + k - 1) // k
            res = 0
            for i in range(r):
                for j in range(c):
                    x, y = i * k, j * k
                    x2, y2 = min(x + k - 1, n - 1), min(y + k - 1, m - 1)
                    zero = acc[x2 + 1][y2 + 1] - acc[x][y2 + 1] - acc[x2 + 1][y] + acc[x][y]
                    # print(x, y, k, zero, k * k - zero)
                    res += min(zero, k * k - zero)
            # print(k, res)
            ans = min(ans, res)
        print(ans)
