    class Arista():
    	def __init__(self,salida,llegada,capacidad,flujo,costo,indice):
    		self.salida = salida
    		self.llegada = llegada
    		self.capacidad = capacidad
    		self.flujo = flujo
    		self.costo = costo
    		self.indice = indice

    	def __str__(self):
