def min_paint_needed():
    INF = 10 ** 18
    MX_SZ = 112
    dp = [[[INF for k in range (MX_SZ)] for j in range (MX_SZ)] for i in range (MX_SZ)]
    best = [[[(INF, INF) for k in range (MX_SZ)] for j in range (MX_SZ)] for i in range (MX_SZ)]

    def read():
        return [int(x) for x in input().split()]

    n, m, k_res = read()
    arr = read()
    cost = []
    for i in range (n):
        cost.append(read())
    dp[0][0][MX_SZ - 1] = 0 #[trees painted][group amount][last color]
    best[0][0][0] = (0, MX_SZ - 1)
    #print(best[0][0][0][1])
    #return
    for i in range (1, n + 1):
        clr = arr[i - 1]
        if clr == 0:
            for j in range (1, k_res + 1):
                for k in range (1, m + 1):
                    dp[i][j][k] = dp[i - 1][j][k] + cost[i - 1][k - 1]
                    if k == best[i - 1][j - 1][0][1]:
                        dp[i][j][k] = min(dp[i][j][k], best[i - 1][j - 1][1][0] + cost[i - 1][k - 1])
                    else:
                        dp[i][j][k] = min(dp[i][j][k], best[i - 1][j - 1][0][0] + cost[i - 1][k - 1])
                    if dp[i][j][k] < best[i][j][0][0]:
                        best[i][j][1] = best[i][j][0]
                        best[i][j][0] = (dp[i][j][k], k)
                    elif dp[i][j][k] < best[i][j][1][0]:
                        best[i][j][1] = (dp[i][j][k], k)
        else:
            for j in range (1, n + 1):
                dp[i][j][clr] = dp[i - 1][j][clr]
                if clr == best[i - 1][j - 1][0][1]:
                    dp[i][j][clr] = min(dp[i][j][clr], best[i - 1][j - 1][1][0])
                else:
                    dp[i][j][clr] = min(dp[i][j][clr], best[i - 1][j - 1][0][0])
                best[i][j][0] = (dp[i][j][clr], clr)
    ans = INF
    for k in range (1, m + 1):
        if dp[n][k_res][k] < ans:
            ans = dp[n][k_res][k]
    if ans == INF:
        ans = -1
    print(ans)

import timedef max_happy_friends():
    n, m =map(int, input().split())
    names={None:0}
    count={i:0 for i in range(1, m+1)}
    a=[0]*(n+1)
    for i in range(n):
        l=list(input().split())
        if l[0]=='2':
            if l[1] not in names:
                names[l[1]]=len(names)
            a[i]=names[l[1]]
            count[a[i]]=count[a[i]]+1
        # else a[i] stays 0
    dense=[set() for _ in range(m+1)]
    bulk=set()
    # filling dense array of arrays
    for i in range(n):
        if a[i]==0:
            bulk.clear()
            continue
        if a[i] in bulk: continue
        for j in bulk:
            dense[j].add(a[i])
            dense[a[i]].add(j)
        bulk.add(a[i])
    res=0
    happy=set()
    unhappy=set()
    mindep=99
    independent=set()
    dependent=set()
    for i in range(1, m+1):
        if len(dense[i])==0: independent.add(i)
        else:
            dependent.add(i)
            if len(dense[i])<mindep:
                mindep=len(dense[i])
    # print([i for i in dependent if mindep==len(dense[i])])
    for k in list(dependent):
        # iterate to... too sly
        happy.clear()
        unhappy.clear()
        bulk.clear()
        bulk.update(dependent)
        happy.add(k)
        bulk.remove(k)
        for j in dense[k]:
            if j in bulk:
                unhappy.add(j)
                bulk.remove(j)
        # now making least connected happy
        while bulk:
            mini = min([len(dense[i]) for i in bulk])
            for i in list(bulk):
                if len(dense[i])==mini and (i in bulk):
                    happy.add(i)
                    bulk.remove(i)
                    for j in dense[i]:
                        if j in bulk:
                            unhappy.add(j)
                            bulk.remove(j)
                    continue
        res=max(res,len(happy))
    print(res+len(independent))

