import sysdef calculate_distances_walked():
    input = sys.stdin.readline
    def solve():
        N, Q = list(map(int, input().split()))
        events = []
        for i in range(N):
            S, T, X = list(map(int, input().split()))
            events.append((S-X-0.5, 1, X))
            events.append((T-X-0.5, 0, X))
        for i in range(Q):
            D = int(input())
            events.append((D, 2, i))
        events.sort()
        anss = [-1] * Q
        PQ = []
        isClosed = dict()
        for tm, tp, x in events:
            if tp == 0:
                isClosed[x] = 0
            elif tp == 1:
                isClosed[x] = 1
                heappush(PQ, x)
            else:
                while PQ:
                    if isClosed[PQ[0]] == 1:
                        anss[x] = PQ[0]
                        break
                    heappop(PQ)
        print(('\n'.join(map(str, anss))))
    solve()

def gravel_operations():
    N,M,C = list(map(int, input().split()))
    tree = [0] * (N+1)

    def add(u,k):
     while u < len(tree):
      tree[u] += k 
      u += u&-u

    def query(k):
     ans = 0
     while k:
      ans += tree[k]
      k -= k&-k

     return ans

    def solve():
     for _ in range(M):
      op = input().split()
      if op[0] == 'Q':
       print(query(int(op[1])) + C)
      else:
       u,v,k = int(op[1]), int(op[2]), int(op[3]) 
       add(u, k)
       add(v+1, -k)

    def __starting_point():
     solve()

    __starting_point()

class Solution:
    def numOfSubarrays(self, arr: List[int]) -> int:
        mod = 10**9+7
        odd_presum_cnt = 0
        par = 0
        for a in arr:
            par ^= a & 1
            if par:
                odd_presum_cnt += 1
        return odd_presum_cnt * (len(arr)+1 - odd_presum_cnt)%mod

