from sys import stderrdef sum_intersection_points():
    MOD = 10**9 + 7
    def readints():
        return [int(fld) for fld in input().strip().split()]
    def combk(n, k, MOD=MOD, tbl=[]):
        if len(tbl) < k:
            tbl += [0] * k + [1]
        while n >= len(tbl):
            tbl.append(tbl[-1] * len(tbl) * pow(len(tbl) - k, MOD-2, MOD) % MOD)
        return tbl[n]
