def is_armstrong_number():
    def power(x, y):
    	if y == 0:
    		return 1
    	if y % 2 == 0:
    		return power(x, y // 2) * power(x, y // 2)

    	return x * power(x, y // 2) * power(x, y // 2)


    # Function to calculate order of the number
    def order(x):
    	# Variable to store of the number
    	n = 0
    	while (x != 0):
    		n = n + 1
    		x = x // 10

    	return n


    # Function to check whether the given
    # number is Armstrong number or not
    def isArmstrong(x):
    	n = order(x)
    	temp = x
    	sum1 = 0

    	while (temp != 0):
    		r = temp % 10
    		sum1 = sum1 + power(r, n)
    		temp = temp // 10

    	# If condition satisfies
    	return (sum1 == x)


    # Driver code

    for _ in range(int(input())):
    	num = int(input())
    	if isArmstrong(num):
    		print("FEELS GOOD")
    	else:
    		print("FEELS BAD")

def process_employee_events():
    n, m = map(int, input().split())
    ev = [tuple(map(int, input().split())) for _ in range(m)]

    g = [[] for _ in range(n + 1)]
    qry = [[] for _ in range(m + 1)]
    roots = set(range(1, n + 1))
    qcnt = 0
    for e in ev:
    	if e[0] == 1:
    		g[e[2]].append(e[1])
    		roots.remove(e[1])
    	elif e[0] == 3:
    		qry[e[2]].append((qcnt, e[1]))
    		qcnt += 1

    tin, tout = [0] * (n + 1), [0] * (n + 1)
    st = [(u, 0) for u in roots]
    time = 0
    while st:
    	u, w = st.pop()
    	if w:
    		tout[u] = time
    		continue
    	time += 1
    	tin[u] = time
    	st.append((u, 1))
    	for v in g[u]:
    		st.append((v, 0))

    p = list(range(n + 1))
    def find(x):
    	if x != p[x]:
    		p[x] = find(p[x])
    	return p[x]

    pcnt = 0
    ans = [None] * qcnt
    for e in ev:
    	if e[0] == 1:
    		p[find(e[1])] = find(e[2])
    	elif e[0] == 2:
    		pcnt += 1
    		for qid, x in qry[pcnt]:
    			ans[qid] = 'YES' if find(e[1]) == find(x) and tin[x] <= tin[e[1]] <= tout[x] else 'NO'

    print(*ans, sep='\n')

from collections import defaultdict


class Solution:
    MAXPRIME=100001
    isPrime=[0 for _ in range(MAXPRIME+1)]
    isPrime[0]=-1;isPrime[1]=-1 #0 and 1 are not prime numbers
    for i in range(2,MAXPRIME):
        if isPrime[i]==0: #i is prime
            for multiple in range(i*i,MAXPRIME+1,i):
                if isPrime[multiple]==0:
                    isPrime[multiple]=i
            isPrime[i] = i

    def largestComponentSize(self, A: List[int]) -> int:
        label = defaultdict(int)

        def findRoot(key):
            if label[key] > 0:
                label[key] = findRoot(label[key])
                return label[key]
            else:
                return key

        def mergeRoot(k1, k2):
            r1, r2 = findRoot(k1), findRoot(k2)  
            if r1 != r2:
                r1, r2 = min(r1, r2), max(r1, r2)
                label[r1] += label[r2]
                label[r2] = r1
            return r1

        for x in A:
            root_id = 0
            prime_factors = set()
            while Solution.isPrime[x]!=-1:
                p = Solution.isPrime[x]
                root_id = findRoot(p) if root_id == 0 else mergeRoot(root_id, p)
                x //= p
            label[root_id] -= 1

        return -min(label.values())

