def is_table_sorted_in_order():
    n, m = list(map(int, input().split()))
    M = [list(map(int, input().split())) for r in range(n)]

    depth = [[1] * m for r in range(n)]

    for c in range(m):
        for r in range(1, n):
            if M[r][c] >= M[r - 1][c]:
                depth[r][c] = depth[r - 1][c] + 1

