def min_teleportation_pipes(n, m, important_pairs):
    from collections import defaultdict

    # Build the adjacency list and reverse adjacency list
    adj = defaultdict(list)
    rev_adj = defaultdict(list)

    for a, b in important_pairs:
        adj[a].append(b)
        rev_adj[b].append(a)

    # Step 1: Determine all reachable nodes for each node through DFS
    def dfs(graph, start, visited):
        stack = [start]
        while stack:
            node = stack.pop()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    reachable = defaultdict(set)
    for i in range(1, n + 1):
        visited_set = set()
        dfs(adj, i, visited_set)
        reachable[i] = visited_set

    # Step 2: Use a modified version of Kahn's algorithm to find SCCs
    from collections import deque

    # To find the strongly connected components using Kahn's algorithm variation
    def find_sccs():
        in_degrees = {i: 0 for i in range(1, n + 1)}
        for edges in adj.values():
            for node in edges:
                in_degrees[node] += 1

        zero_in_degrees = deque([i for i in range(1, n + 1) if in_degrees[i] == 0])
        topological_order = []

        while zero_in_degrees:
            node = zero_in_degrees.popleft()
            topological_order.append(node)

            for neighbor in adj[node]:
                in_degrees[neighbor] -= 1
                if in_degrees[neighbor] == 0:
                    zero_in_degrees.append(neighbor)

        return topological_order

    topo_sorted_nodes = find_sccs()

    # Step 3: Calculate the minimum number of teleportation pipes
    min_pipes_needed = 0
    reachable_set = set()

    for node in topo_sorted_nodes[::-1]:  # reversed topological order
        if node not in reachable_set:
            for reachable_node in reachable[node]:
                reachable_set.add(reachable_node)
            min_pipes_needed += 1

    return min_pipes_needed

