class Solution:
     def trap(self, height):
         """
         :type height: List[int]
         :rtype: int
         """
         if not height:
             return 0
         result = 0
         left = 0
         right = len(height) - 1
         while left < right:
             if height[left] <= height[right]:
                 tmp = height[left]
                 left += 1
                 while left < right and height[left] <= tmp:
                     result += tmp - height[left]
                     left += 1
             else:
                 tmp = height[right]
                 right -= 1
                 while left < right and height[right] <= tmp:
                     result += tmp - height[right]
                     right -=1 
         return result

class Solution(object):
     def hIndex(self, citations):
         """
         :type citations: List[int]
         :rtype: int
         """
         n = len(citations)
         l = 0
         r = n-1
         while l <= r:
             m = (l + r) // 2
             if m == 0 and citations[m] >= n - m or  citations[m-1] < n - (m-1) and citations[m] >= n-m:
                 return n-m
             if citations[m] < n - m:
                 l = m+1
             else:
                 r = m
         return 0

class Solution:
    def bagOfTokensScore(self, tokens: List[int], P: int) -> int:
        tokens = sorted(tokens)
        left = 0
        right = len(tokens) - 1
        points = 0

        if len(tokens) == 1:
            if tokens[0] <= P:
                return 1
        if len(tokens) == 0:
            return 0
        while left < right:

            if tokens[left] <= P:
                P -= tokens[left]
                left += 1
                points += 1

            elif tokens[left] > P and points > 0:
                P += tokens[right]
                points -= 1
                right -= 1


            elif points == 0 and tokens[left] > P:
                break
        if P >= tokens[left]:
            points += 1
        return points

class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:

        flowersN = len(bloomDay)
        if flowersN < m*k:
            return -1

        def checkFlowers(x):
            count = 0
            gotFlowers = 0
            for num in bloomDay:
                if num <= x:
                    count += 1
                    if count == k:
                        gotFlowers += 1
                        count = 0
                else:
                    count = 0
            # print(gotFlowers, x, m)
            return gotFlowers >= m

        sortedDays = sorted(list(set(bloomDay)))
        l = 0
        r = len(sortedDays) - 1
        if checkFlowers(sortedDays[l]):
            return sortedDays[l]
        while l < r:
            mm = (l + r)//2
            if checkFlowers(sortedDays[mm]):
                r = mm
            else:
                l = mm+ 1
        return sortedDays[l]

