            leaf.add(i)
    ban=set([])
    while leaf:
        v=leaf.pop()
        ban.add(v)
        deg[v]=0
        for nv in edge[v]:
            deg[nv]-=1
            if deg[nv]==1 and c[nv]=="B":
                leaf.add(nv)
    for i in range(N):
        edge[i]=[nv for nv in edge[i] if nv not in ban]
    root=-1
    for i in range(N):
        if i not in ban:
            root=i
    parent=[-2]*N
    deq=deque([(root,-1)])
    node=[]
    while deq:
        v,pv=deq.popleft()
        parent[v]=pv
        node.append(v)
        for nv in edge[v]:
            if nv!=pv:
                deq.append((nv,v))
    node=node[::-1]
    for i in range(N):
        edge[i]=[nv for nv in edge[i] if nv!=parent[i]]
    check=True
