import sysdef minimum_expected_moves():
    3
    class CumTree:

        def __init__(self, a, b):
            self.a = a
            self.b = b
            self.count = 0
            if a == b:
                return
            mid = (a + b) // 2
            self.levo = CumTree(a, mid)
            self.desno = CumTree(mid+1, b)

        def manjsi(self, t):
            if self.a >= t:
                return 0
            if self.b < t:
                return self.count
            return self.levo.manjsi(t) + self.desno.manjsi(t)

        def vstavi(self, t):
            if self.a <= t <= self.b:
                self.count += 1
                if self.a == self.b:
                    return
                self.levo.vstavi(t)
                self.desno.vstavi(t)

    n = int(sys.stdin.readline())
    p = [int(x) for x in sys.stdin.readline().strip().split()]
    ct = CumTree(1, 4096)
    vsota = 0
    while len(p) > 0:
        x = p.pop()
        vsota += ct.manjsi(x)
        ct.vstavi(x)
    k, d = vsota // 2, vsota % 2
    print("%f" % (4*k + d))

def find_lexicographically_smallest_string():
    m = int(input())
    s = input().strip()

    sa = [0] * len(s)
    for i in range(len(s)):
    	sa[i] = ord(s[i]) - ord('a')

    sa = [-1] + sa + [-1]

    def check_value(sa, m, threshold):
    	prev_ind = 0
    	for i in range(len(sa)):
    		if sa[i] <= threshold:
    			if i - prev_ind <= m:
    				prev_ind = i
    			else:
    				return False
    	return True

    def get_indexes(sa, threshold):
    	seq = [i for i in range(len(sa)) if sa[i] <= threshold]
    	# seq = []
    	# for i in range(len(sa)):
    	# 	if sa[i] < threshold:
    	# 		seq[i].append(sa[i], i)
    	return seq

    def filter_indexes(sa, seq, el, m):
    	new_seq = [0]
    	for i in range(1, len(seq) - 1):
    		if sa[seq[i]] != el or (sa[seq[i]] == el and seq[i+1] - new_seq[-1] > m):
    			new_seq.append(seq[i])
    	return new_seq[1:]


    threshold = -1
    while (not check_value(sa, m, threshold)):
    	# print(threshold, get_indexes(sa, threshold))
    	threshold += 1
    # print(threshold, get_indexes(sa, threshold), sa)

    seq = get_indexes(sa, threshold)
    seq = filter_indexes(sa, seq, threshold, m)

    s = ''.join(sorted([chr(ord('a') + sa[x]) for x in seq]))
    print(s)

import sysdef restore_permutation():
    input = sys.stdin.readline
    n=int(input())
    A=list(map(int,input().split()))
    BIT=[0]*(n+1)
    def update(v,w):
        while v<=n:
            BIT[v]+=w
            v+=(v&(-v))
    def getvalue(v):
        ANS=0
        while v!=0:
            ANS+=BIT[v]
            v-=(v&(-v))
        return ANS
    for i in range(1,n+1):
        update(i,i)
    ANS=[-1]*n
    for i in range(n-1,-1,-1):
        MIN=0
        MAX=n
        k=A[i]
        while True:
            x=(MIN+MAX+1)//2
            if getvalue(x)>k:
                if getvalue(x-1)==k:
                    ANS[i]=x
                    break
                else:
                    MAX=x
            else:
                MIN=x
        update(x,-x)

    print(*ANS)

