from functools import reducedef calculate_min_travel_cost():
    n, x, y = [int(x) for x in input().split()]
    E = defaultdict(set)
    for i in range(n-1):
        u, v = [int(x) for x in input().split()]
        E[u].add(v)
        E[v].add(u)
    if x > y:
        for v in E:
            if len(E[v]) == n-1:
                print((n-2)*y + x)
                break
            elif len(E[v]) > 1:
                print((n-1)*y)
                break
    else:
        visited = {v : False for v in E}
        stack = [1]
        topsorted = deque()
        while stack:
            v = stack.pop()
            if visited[v]: continue
            visited[v] = True
            topsorted.appendleft(v)
            stack.extend(E[v])
        chopped = set()
        ans = 0
        for v in topsorted:
            ans += max(0, len(E[v])-2)
            if len(E[v]) > 2:
                S = E[v].intersection(chopped)
                S1 = {S.pop(), S.pop()}
                for u in E[v]:
                    if not u in S1:
                        E[u].remove(v)
                E[v].clear()
                E[v].update(S1)
            chopped.add(v)
        print(ans*y + (n-1-ans)*x)

def find_maximum_f_p():
    n = int(input())
    edges = [[int(x) for x in input().split()] for i in range(n-1)]
    edges = sorted(edges)
    use_count = [0]+[int(input()) for i in range(n)]
    lo,hi = 0,10000
    def getpar(par,u):
        if par[par[u]] == par[u]:
            return par[u]
        par[u] = getpar(par,par[u])
        return par[u]
    def unite(par,sz,use,u,v):
        u = getpar(par,u)
        v = getpar(par,v)
        par[u] = v
        sz[v] += sz[u]
        use[v] += use[u]
    def solve(fp):
        par = [i for i in range(n+1)]
        sz = [1 for i in range(n+1)]
        use = [use_count[i] for i in range(n+1)]
        for edge in edges:
            if edge[2] < fp:
                unite(par,sz,use,edge[0],edge[1])
        total_use = sum(use_count)
        for i in range(n+1):
            p = getpar(par,i)
            if(p == i):
                if(total_use - use[p] < sz[p]):
                    return False
        return True
    while lo < hi:
        mid = (lo+hi+1)//2
        if solve(mid):
            lo = mid
        else:
            hi = mid-1
    print(lo)

from functools import reduce
from itertools import accumulate,chaindef calculate_road_improvement_ways():
    class Graph:
        def __init__(self, n_vertices, edges, directed=True, weighted=False):
            self.n_vertices = n_vertices
            self.edges = edges
            self.directed = directed
            self.weighted = weighted
        @property
        def adj(self):
            try:
                return self._adj
            except AttributeError:
                adj = [[] for _ in range(self.n_vertices)]
                def d_w(e):
                    adj[e[0]].append((e[1],e[2]))
                def ud_w(e):
                    adj[e[0]].append((e[1],e[2]))
                    adj[e[1]].append((e[0],e[2]))
                def d_uw(e):
                    adj[e[0]].append(e[1])
                def ud_uw(e):
                    adj[e[0]].append(e[1])
                    adj[e[1]].append(e[0])
                helper = (ud_uw, d_uw, ud_w, d_w)[self.directed+self.weighted*2]
                for e in self.edges:
                    helper(e)
                self._adj = adj
                return adj
    class RootedTree(Graph):
        def __init__(self, n_vertices, edges, root_vertex):
            self.root = root_vertex
            super().__init__(n_vertices, edges, False, False)
        @property
        def parent(self):
            try:
                return self._parent
            except AttributeError:
                adj = self.adj
                parent = [None]*self.n_vertices
                parent[self.root] = -1
                stack = [self.root]
                for i in range(self.n_vertices):
                    v = stack.pop()
                    for u in adj[v]:
                        if parent[u] is None:
                            parent[u] = v
                            stack.append(u)
                self._parent = parent
                return parent
        @property
        def children(self):
            try:
                return self._children
            except AttributeError:
                children = [None]*self.n_vertices
                for v,(l,p) in enumerate(zip(self.adj,self.parent)):
                    children[v] = [u for u in l if u != p]
                self._children = children
                return children
        @property
        def dfs_order(self):
            try:
                return self._dfs_order
            except AttributeError:
                order = [None]*self.n_vertices
                children = self.children
                stack = [self.root]
                for i in range(self.n_vertices):
                    v = stack.pop()
                    order[i] = v
                    for u in children[v]:
                        stack.append(u)
                self._dfs_order = order
                return order
    def rerooting(rooted_tree, merge, identity, finalize):
        N = rooted_tree.n_vertices
        parent = rooted_tree.parent
        children = rooted_tree.children
        order = rooted_tree.dfs_order
        # from leaf to parent
        dp_down = [None]*N
        for v in reversed(order[1:]):
            dp_down[v] = finalize(reduce(merge,
                (dp_down[c] for c in children[v]),
                identity))
        # from parent to leaf
        dp_up = [None]*N
        dp_up[0] = identity
        for v in order:
            if len(children[v]) == 0:
                continue
            temp = (dp_up[v],)+tuple(dp_down[u] for u in children[v])+(identity,)
            left = tuple(accumulate(temp,merge))
            right = tuple(accumulate(reversed(temp[2:]),merge))
            for u,l,r in zip(children[v],left,reversed(right)):
                dp_up[u] = finalize(merge(l,r))
        res = [None]*N
        for v,l in enumerate(children):
            res[v] = reduce(merge,
                        (dp_down[u] for u in children[v]),
                        identity)
            res[v] = finalize(merge(res[v], dp_up[v]))
        return res
    def solve(T):
        MOD = 10**9 + 7
        def merge(x,y):
            return (x*y)%MOD
        def finalize(x):
            return x+1
        return [v-1 for v in rerooting(T,merge,1,finalize)]
    def __starting_point():
        N = int(input())
        edges = [(i+1,p-1) for i,p in enumerate(map(int,input().split()))]
        T = RootedTree(N, edges, 0)
        print(*solve(T))
    __starting_point()

