def min_seconds_to_destroy_gemstones():
    n = int(input())
    C = list(map(int, input().split()))

    dp = [[0]*n for _ in range(n)]
    for i in range(n) :
        dp[i][i] = 1

    for i in range(n-2, -1, -1) :
        for j in range(i+1, n) :
            dp[i][j] = 1 + dp[i+1][j]
            if C[i] == C[i+1] : dp[i][j] = min( dp[i][j], 1 + (dp[i+2][j] if i+2 < n else 0) )
            for k in range(i+2, j) :
                if C[i] == C[k] : dp[i][j] = min( dp[i][j], dp[i+1][k-1] + dp[k+1][j] )
            if C[i] == C[j] and j-i > 1:
                dp[i][j] = min( dp[i][j], dp[i+1][j-1] )

    print( dp[0][n-1] )

def can_religions_coexist():
    n, q = map(int, input().split())
    s = '!' + input()

    nxt = [[n + 1] * (n + 2) for _ in range(26)]
    for i in range(n - 1, -1, -1):
        c = ord(s[i + 1]) - 97
        for j in range(26):
            nxt[j][i] = nxt[j][i + 1]
        nxt[c][i] = i + 1

    w = [[-1], [-1], [-1]]
    idx = lambda i, j, k: i * 65536 + j * 256 + k
    dp = [0] * (256 * 256 * 256)
    def calc(fix=None):
        r = list(map(range, (len(w[0]), len(w[1]), len(w[2]))))
        if fix is not None: r[fix] = range(len(w[fix]) - 1, len(w[fix]))
        for i in r[0]:
            for j in r[1]:
                for k in r[2]:
                    dp[idx(i, j, k)] = min(nxt[w[0][i]][dp[idx(i - 1, j, k)]] if i else n + 1,
                                           nxt[w[1][j]][dp[idx(i, j - 1, k)]] if j else n + 1,
                                           nxt[w[2][k]][dp[idx(i, j, k - 1)]] if k else n + 1)
                    if i == j == k == 0: dp[idx(i, j, k)] = 0

    out = []
    for _ in range(q):
        t, *r = input().split()
        if t == '+':
            i, c = int(r[0]) - 1, ord(r[1]) - 97
            w[i].append(c)
            calc(i)
        else:
            i = int(r[0]) - 1
            w[i].pop()
        req = dp[idx(len(w[0]) - 1, len(w[1]) - 1, len(w[2]) - 1)]
        out.append('YES' if req <= n else 'NO')

    print(*out, sep='\n')

def is_color_weight_allocation_possible():
    N=int(input())
    P=[-1]+[int(i)-1 for i in input().split()]
    X=[int(i) for i in input().split()]
    Q=[[] for i in range(N)]
    for i in range(1,N):
        Q[P[i]].append(i)
    dp=[0 for i in range(N)]
    INF=10**9+7
    def solve(i):
        cur=[INF for j in range(X[i]+1)]
        cur[0]=0
        for j in Q[i]:
            solve(j)
            prv=[k for k in cur]
            cur=[INF for k in range(X[i]+1)]
            for acc in range(len(prv)):
                if prv[acc]<INF:
                    if acc+X[j]<=X[i]:
                        cur[acc+X[j]]=min(cur[acc+X[j]],prv[acc]+dp[j])
                    if acc+dp[j]<=X[i]:
                        cur[acc+dp[j]]=min(cur[acc+dp[j]],prv[acc]+X[j])
        dp[i]=min(cur)
    solve(0)
    if dp[0]<INF:
        print("POSSIBLE")
    else:
        print("IMPOSSIBLE")

from itertools import permutations
from bisect import bisect_leftdef expected_longest_increasing_subsequence_mod():
    inf = 10 ** 18
    mod = 10 ** 9 + 7
    def nCr(n, r, mod=10**9+7):
        if r < 0 or r > n:
            return 0
        res = 1
        div = 1
        r = min(r, n - r)
        for i in range(r):
            res = res * (n - i) % mod
            div = div * (i + 1) % mod
        return res * pow(div, mod-2, mod) % mod
    def calc_lis(A):
        L = [A[0]]
        for a in A[1:]:
            if a > L[-1]:
                L.append(a)
            else:
                L[bisect_left(L, a)] = a
        return len(L)
    def enum(N, A):
        diff = [A[0]] + [r - l for l, r in zip(A[:-1], A[1:])]
        dp = [[0] * (N + 1) for _ in range(N + 1)]
        dp[0][0] = 1
        for i in range(1, N + 1):
            for j in range(i, N + 1):
                for k in range(i - 1, j + 1):
                    dp[i][j] += dp[i - 1][k] * nCr(diff[i - 1], j - k)
                    dp[i][j] %= mod
        return dp[N][N]
    def main():
        N = int(input())
        A = list(map(int, input().split()))
        pair = [(0,)]
        for _ in range(1, N):
            nxt = []
            for p in pair:
                v = p[-1]
                nxt.append(p + (v,))
                nxt.append(p + (v+1,))
            pair = nxt
        ans = 0
        for p in pair:
            sz = p[-1] + 1
            for order in set(permutations(p)):
                arr = [inf] * sz
                for i, a in zip(order, A):
                    arr[i] = min(arr[i], a)
                for i in reversed(range(sz - 1)):
                    arr[i] = min(arr[i], arr[i + 1])
                ans += enum(sz, arr) * calc_lis(order)
                ans %= mod
        for a in A:
            ans *= pow(a, mod - 2, mod)
            ans %= mod
        print(ans)
    main()

def find_final_carrot_juiciness():
    def evens(A):
        n = len(A)
        l = n//2-1; r = n//2
        if len(A)%2 == 1: l+= 1
        ans = [max(A[l], A[r])]
        while r < n-1:
            l-= 1; r+= 1
            ans.append(max(ans[-1], A[l], A[r]))
        return ans

    def interleave(A, B):
        q = []
        for i in range(len(B)): q+= [A[i], B[i]]
        if len(A) != len(B): q.append(A[-1])
        return q

    n = int(input())
    A = list(map(int,input().split()))
    M = [min(A[i],A[i+1]) for i in range(n-1)]
    ansA = evens(A)
    ansM = evens(M) if n>1 else []
    if n%2 == 0: print(*interleave(ansA, ansM[1:]), max(A))
    else: print(*interleave(ansM, ansA[1:]), max(A))

