def count_rectangles_with_sum_a():
    def f(t, k):
        i, j = 0, 1
        s, d = 0, t[0]
        n = len(t)
        while j <= n:
            if d > k:
                d -= t[i]
                i += 1
            elif d == k:
                if t[i] and (j == n or t[j]): s += 1
                else:
                    a, b = i - 1, j - 1
                    while j < n and t[j] == 0: j += 1
                    while t[i] == 0: i += 1
                    s += (i - a) * (j - b)
                if j < n: d += t[j]
                d -= t[i]
                i += 1
                j += 1                
            else:
                if j < n: d += t[j]
                j += 1
        return s

    s, n = 0, int(input())
    t = list(map(int, input()))
    if n:
        k = sum(t)
        if k == 0: print(0)
        else:
            p = [(i, n // i) for i in range(max(1, n // k), int(n ** 0.5) + 1) if n % i == 0]
            for a, b in p:
                if a != b: s += 2 * f(t, a) * f(t, b)
                else:
                    k = f(t, a)
                    s += k * k
            print(s)
    else:
        n = len(t)
        m = n * (n + 1)
        s = j = 0
        while j < n:
            if t[j] == 0:
                i = j
                j += 1
                while j < n and t[j] == 0: j += 1
                k = ((j - i) * (j - i + 1)) // 2
                s += k
            j += 1
        print((m - s) * s)

import sys
from collections import defaultdictdef min_paint_cost():
    class MaxFlow(object):
        def __init__(self):
            self.edges = defaultdict(lambda: defaultdict(lambda: 0))
        def add_edge(self, u, v, capacity=float('inf')):
            self.edges[u][v] = capacity
        def bfs(self, s, t):
            open_q = [s]
            visited = set()
            parent = dict()
            while open_q:
                close_q = []
                for node in open_q:
                    for v, capacity in list(self.edges[node].items()):
                        if v not in visited and capacity > 0:
                            close_q.append(v)
                            parent[v] = node
                            visited.add(v)
                            if v == t:
                                result = []
                                n2 = v
                                n1 = node
                                while n1 != s:
                                    result.append((n1, n2))
                                    n2 = n1
                                    n1 = parent[n1]
                                result.append((n1, n2))
                                return result
                open_q = close_q
            return None
        def solve(self, s, t):
            flow = 0
            route = self.bfs(s, t)
            while route is not None:
                new_flow = float('inf')
                for _, (n1, n2) in enumerate(route):
                    new_flow = min(new_flow, self.edges[n1][n2])
                for _, (n1, n2) in enumerate(route):
                    self.edges[n1][n2] -= new_flow
                    self.edges[n2][n1] += new_flow
                flow += new_flow
                route = self.bfs(s, t)
            return flow
        def __str__(self):
            result = "{ "
            for k, v in list(self.edges.items()):
                result += str(k) + ":" + str(dict(v)) + ", "
            result += "}"
            return result
    def main():
        (n, m) = tuple([int(x) for x in input().split()])
        r = []
        xs = set()
        ys = set()
        for i in range(m):
            (x1, y1, x2, y2) = tuple(int(x) for x in input().split())
            r.append((x1, y1, x2, y2))
            xs.add(x1)
            xs.add(x2 + 1)
            ys.add(y1)
            ys.add(y2 + 1)
        xx = sorted(xs)
        yy = sorted(ys)
        xsize = len(xs)
        ysize = len(ys)
        grid = []
        for i in range(ysize):
            grid.append([False] * xsize)
        for rect in r:
            x1 = rect[0]
            y1 = rect[1]
            x2 = rect[2]
            y2 = rect[3]
            for i, y in enumerate(yy):
                for j, x in enumerate(xx):
                    if x1 <= x and y1 <= y and x2 >= x and y2 >= y:
                        grid[i][j] = True
        f = MaxFlow()
        for i in range(len(yy)):
            for j in range(len(xx)):
                if grid[i][j]:
                    f.add_edge(1 + i, len(yy) + 1 + j, float('inf'))
        for i in range(len(yy) - 1):
            f.add_edge(0, i + 1, yy[i + 1] - yy[i])
        for i in range(len(xx) - 1):
            f.add_edge(len(yy) + 1 + i, len(xx) + len(yy) + 1, xx[i + 1] - xx[i])
        # print(xx)
        # print(yy)
        # print(f)
        print(f.solve(0, len(xx) + len(yy) + 1))
    def __starting_point():
        main()
    __starting_point()

