    for i in range(n):

        nd = {}

        na = a[i]
        while divlis[na] != -1:

            if divlis[na] not in nd:
                nd[divlis[na]] = 0
            nd[divlis[na]] += 1

            na //= divlis[na]

        if na != 1:
            if na not in nd:
                nd[na] = 1
            else:
                nd[na] += 1

        for x in nd:
            if x not in dic:
                dic[x] = []
            dic[x].append(nd[x])

    ans = 1

    for i in dic:

        if len(dic[i]) < n-1:
            #print (i,"a")
