import sys
from io import BytesIO, IOBasedef count_lonely_numbers():
    def main():
        pass
    # region fastio
    BUFSIZE = 8192
    class FastIO(IOBase):
        newlines = 0
        def __init__(self, file):
            self._fd = file.fileno()
            self.buffer = BytesIO()
            self.writable = "x" in file.mode or "r" not in file.mode
            self.write = self.buffer.write if self.writable else None
        def read(self):
            while True:
                b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
                if not b:
                    break
                ptr = self.buffer.tell()
                self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
            self.newlines = 0
            return self.buffer.read()
        def readline(self):
            while self.newlines == 0:
                b = os.read(self._fd, max(os.fstat(self._fd).st_size, BUFSIZE))
                self.newlines = b.count(b"\n") + (not b)
                ptr = self.buffer.tell()
                self.buffer.seek(0, 2), self.buffer.write(b), self.buffer.seek(ptr)
            self.newlines -= 1
            return self.buffer.readline()
        def flush(self):
            if self.writable:
                os.write(self._fd, self.buffer.getvalue())
                self.buffer.truncate(0), self.buffer.seek(0)
    class IOWrapper(IOBase):
        def __init__(self, file):
            self.buffer = FastIO(file)
            self.flush = self.buffer.flush
            self.writable = self.buffer.writable
            self.write = lambda s: self.buffer.write(s.encode("ascii"))
            self.read = lambda: self.buffer.read().decode("ascii")
            self.readline = lambda: self.buffer.readline().decode("ascii")
    sys.stdin, sys.stdout = IOWrapper(sys.stdin), IOWrapper(sys.stdout)
    input = lambda: sys.stdin.readline().rstrip("\r\n")
    primes = []
    prime = [True] * (10 ** 6  +5)
    prime[0] = False
    for i in range(2, 10 ** 6):
        if prime[i]:
            for j in range(2 * i, 10 ** 6 + 5, i):
                prime[j] = False
    pref = [0]
    for i in range(1, 10 ** 6 + 5):
        pref.append(pref[-1])
        if prime[i]:
            pref[-1] += 1
        s = round(i ** .5)
        if  s * s == i and prime[s] and i != 1:
            pref[-1] -= 1
    n = int(input())
    l = list(map(int, input().split()))
    out = []
    for v in l:
        out.append(pref[v])
    print('\n'.join(map(str,out)))

from math import sqrt, ceildef compute_k_composite_modulo():
    MAX_N = 10 ** 6 * 2 
    prime = []
    isPrime = [True for i in range(MAX_N)]
    for i in range(2, MAX_N):
        if isPrime[i]:
            prime.append(i)
            for j in range(i * i, MAX_N, i):
                isPrime[j] = False
    def factor(a):
        divs = []
        for i in prime:
            cnt = 0
            while a % i == 0:
                a //= i
                cnt += 1
            if cnt:
                divs.append((i, cnt,))
        if a > 1:
            divs.append((a, 1,))
        return divs
    def f(n):
        ans = 1
        for div in factor(n):
            ans *= div[0] ** (div[1] - 1) * (div[0] - 1)
        return ans
    def g(n):
        return n
    def F(n, k):
        cur = n
        for i in range(1, k + 1):
            #print(i)
            #print(factor(cur))
            if i == 1:
                cur = f(g(cur))
            elif i % 2 == 0:
                cur = g(cur)
            else:
                cur = f(cur)
            #print(i, cur)
            if cur == 1:
                break
        return cur % (10 ** 9 + 7)
    n, k = [int(i) for i in input().split(' ')]
    #print(factor(n - 1))
    print(F(n, k))

def determine_knight_conquerors():
    n, m = map(int, input().split())
    p, d = [0] * (n + 2), [0] * (n + 2)
    for i in range(m):
        l, r, x = map(int, input().split())
        while l < x:
            if d[l]:
                k = d[l]
                d[l] = x - l
                l += k
            else:
                d[l], p[l] = x - l, x
                l += 1
        l += 1
        r += 1
        while d[r]: r += d[r]
        while l < r:
            if d[l]:
                k = d[l]
                d[l] = r - l
                l += k
            else:
                d[l], p[l] = r - l, x
                l += 1
    print(' '.join(map(str, p[1: -1])))

