def max_sum_after_k_swaps():
    def solve(a,l,r,k):
        out = sorted(a[:l]+a[r:],reverse=True)
        inside = sorted(a[l:r])
        cur = sum(a[l:r])
        for i in range(min(k,len(inside),len(out))):
            if out[i] > inside[i]:
                cur += out[i]-inside[i]
            else:
                break
        return cur

    n,k = [int(x) for x in input().split()]
    a = [int(x) for x in input().split()]
    assert len(a) == n

    best = a[0]
    for l in range(n):
        for r in range(l+1,n+1):
            cur = solve(a,l,r,k)
            if cur > best:
                best = cur

    print(best)

def max_strength_per_group_size():
    def read_data():
        n = int(input())
        hs = list(map(int, input().split()))
        return n, hs


    def solve(n, hs):
        left = get_left_index(n, hs)
        right = get_right_index(n, hs)
        vals = [[] for i in range(n)]
        for h, l, r in zip(hs, left, right):
            vals[r - l - 2].append(h)
        min_hs = []
        min_h = - float('inf')
        for val in vals[::-1]:
            for v in val:
                min_h = max(min_h, v)
            min_hs.append(min_h)
        print(* min_hs[::-1])


    def get_left_index(n, hs):
        left = []
        stack = []
        for i, h in enumerate(hs):
            while stack and hs[stack[-1]] >= h:
                del stack[-1]
            if stack:
                left.append(stack[-1])
            else:
                left.append(-1)
            stack.append(i)
        return left


    def get_right_index(n, hs):
        hs.reverse()
        tmp = get_left_index(n, hs)
        hs.reverse()
        tmp.reverse()
        right = [n - 1 - a for a in tmp]
        return right

    n, hs = read_data()
    solve(n, hs)

import sysdef find_next_tolerable_string():
    3
    def solve(s, k):
        l = len(s)
        for i in range(l-1, -1, -1):
            prev = s[max(i-2, 0):i]
            z = s[i] + 1
            while z in prev:
                z += 1
            if z >= k:
                continue
            # Gotcha!
            ret = s[:i] + [z]
            while len(ret) < l:
                prev = ret[max(len(ret)-2, 0):len(ret)]
                z = 0
                while z in prev:
                    z += 1
                ret.append(z)
            return ret
        return None
    def __starting_point():
        l, k = list(map(int, sys.stdin.readline().split()))
        s = [ord(c) - ord('a') for c in sys.stdin.readline().strip()]
        ans = solve(s, k)
        if ans is None:
            print('NO')
        else:
            print(''.join(chr(ord('a') + x) for x in ans))
    __starting_point()

